!> Benchmarks.
!
! ## Notes
!
! -   Written in "free form" Fortran 95.
!
!<
program bench
  implicit none
  ! ..
  ! Local constants:
  character(5), parameter :: name = 'ctrsm' ! if changed, be sure to adjust length
  integer, parameter :: iterations = 1000000
  integer, parameter :: repeats = 3
  integer, parameter :: min = 1
  integer, parameter :: max = 3
  ! ..
  ! Run the benchmarks:
  call main()
  ! ..
  ! Functions:
contains
  ! ..
  ! Prints the TAP version.
  ! ..
  subroutine print_version()
    print '(A)', 'TAP version 13'
  end subroutine print_version
  ! ..
  ! Prints the TAP summary.
  !
  ! @param {integer} total - total number of tests
  ! @param {integer} passing - total number of passing tests
  ! ..
  subroutine print_summary( total, passing )
    ! ..
    ! Scalar arguments:
    integer, intent(in) :: total, passing
    ! ..
    ! Local variables:
    character(len=999) :: str, tmp
    ! ..
    ! Intrinsic functions:
    intrinsic adjustl, trim
    ! ..
    print '(A)', '#'
    ! ..
    write (str, '(I15)') total ! TAP plan
    tmp = adjustl( str )
    print '(A,A)', '1..', trim( tmp )
    ! ..
    print '(A,A)', '# total ', trim( tmp )
    ! ..
    write (str, '(I15)') passing
    tmp = adjustl( str )
    print '(A,A)', '# pass  ', trim( tmp )
    ! ..
    print '(A)', '#'
    print '(A)', '# ok'
  end subroutine print_summary
  ! ..
  ! Prints benchmarks results.
  !
  ! @param {integer} iterations - number of iterations
  ! @param {double} elapsed - elapsed time in seconds
  ! ..
  subroutine print_results( iterations, elapsed )
    ! ..
    ! Scalar arguments:
    double precision, intent(in) :: elapsed
    integer, intent(in) :: iterations
    ! ..
    ! Local variables:
    double precision :: rate
    character(len=999) :: str, tmp
    ! ..
    ! Intrinsic functions:
    intrinsic dble, adjustl, trim
    ! ..
    rate = dble( iterations ) / elapsed
    ! ..
    print '(A)', '  ---'
    ! ..
    write (str, '(I15)') iterations
    tmp = adjustl( str )
    print '(A,A)', '  iterations: ', trim( tmp )
    ! ..
    write (str, '(f100.9)') elapsed
    tmp = adjustl( str )
    print '(A,A)', '  elapsed: ', trim( tmp )
    ! ..
    write( str, '(f100.9)') rate
    tmp = adjustl( str )
    print '(A,A)', '  rate: ', trim( tmp )
    ! ..
    print '(A)', '  ...'
  end subroutine print_results
  ! ..
  ! Runs a benchmark.
  !
  ! @param {integer} iterations - number of iterations
  ! @param {integer} N - matrix dimension
  ! @return {double} elapsed time in seconds
  ! ..
  double precision function benchmark( iterations, N )
    ! ..
    ! External functions:
    interface
      subroutine ctrsm( side, uplo, transa, diag, M, N, alpha, A, LDA, B, LDB )
        complex :: alpha, A(*), B(*)
        integer :: M, N, LDA, LDB
        character :: side, uplo, transa, diag
      end subroutine ctrsm
    end interface
    ! ..
    ! Scalar arguments:
    integer, intent(in) :: iterations, N
    ! ..
    ! Local scalars:
    double precision :: elapsed, r1, r2
    real :: t1, t2
    integer :: i
    ! ..
    ! Local arrays:
    complex, allocatable :: A(:,:), B(:,:)
    ! ..
    ! Local scalar:
    complex :: alpha
    ! ..
    ! Intrinsic functions:
    intrinsic random_number, cpu_time, cmplx
    ! ..
    ! Allocate arrays:
    allocate( A(N,N) )
    allocate( B(N,N) )
    ! ..
    call random_number( r1 )
    call random_number( r2 )
    alpha = cmplx( (real(r1)*0.5), (real(r2)*0.5) )
    do i = 1, N*N
      call random_number( r1 )
      call random_number( r2 )
      A( mod(i-1,N)+1, (i-1)/N+1 ) = cmplx( real(r1)*10.0-5.0, real(r2)*10.0-5.0 )
      B( mod(i-1,N)+1, (i-1)/N+1 ) = cmplx( real(r1)*10.0-5.0, real(r2)*10.0-5.0 )
    end do
    ! ..
    call cpu_time( t1 )
    ! ..
    do i = 1, iterations
      call ctrsm( 'L', 'U', 'N', 'N', N, N, alpha, A, N, B, N )
      if ( B(1,1) /= B(1,1) ) then
        print '(A)', 'should not return NaN'
        exit
      end if
    end do
    ! ..
    call cpu_time( t2 )
    ! ..
    elapsed = t2 - t1
    ! ..
    if ( B(1,1) /= B(1,1) ) then
      print '(A)', 'should not return NaN'
    end if
    ! ..
    ! Deallocate arrays:
    deallocate( A )
    deallocate( B )
    ! ..
    benchmark = elapsed
    return
  end function benchmark
  ! ..
  ! Main execution sequence.
  ! ..
  subroutine main()
    ! ..
    ! Local variables:
    integer :: count, iter, len, i, j
    double precision :: elapsed
    character(len=999) :: str, tmp
    ! ..
    ! Intrinsic functions:
    intrinsic adjustl, trim
    ! ..
    call print_version()
    count = 0
    do i = min, max
      len = 10**i
      iter = iterations / 10**(i-1)
      do j = 1, repeats
        count = count + 1
        ! ..
        write (str, '(I15)') len
        tmp = adjustl( str )
        print '(A,A,A,A)', '# fortran::', name, ':N=', trim( tmp )
        ! ..
        elapsed = benchmark( iter, len )
        ! ..
        call print_results( iter, elapsed )
        ! ..
        write (str, '(I15)') count
        tmp = adjustl( str )
        print '(A,A,A)', 'ok ', trim( tmp ), ' benchmark finished'
      end do
    end do
    call print_summary( count, count )
  end subroutine main
end program bench
